const Q=require('./aquatic'),assert=require('node:assert/strict'),fs=require('fs');let tests=[],results={};function ck(name,x){assert.ok(x,name);tests.push(name)}function run(s,n){let max=0;for(let i=0;i<n;i++){Q.tick(s);for(let x of Object.values(s.last)){assert.ok(Number.isFinite(x)&&Math.abs(x)<1e-6,JSON.stringify(s.last));max=Math.max(max,Math.abs(x))}for(let r of s.aqua)for(let k of Q.names)for(let e of ['c','n','p'])assert.ok(r[k][e]>=-1e-10,`${k}:${e}`)}return max}
let s=Q.create();let max=run(s,120),m=Q.metrics(s),ev=s.aquaEvents;ck('C/N/P/água e estoques não negativos, 120 passos',max<1e-6);for(let k of ['restingHatch','shrimpSpawn','shrimpHatch','recolonization','frogSpawn','frogHatch','frogMature','birdMeals','birdSpawn','birdHatch','birdCare','birdFledge'])ck(k,ev[k]>0);results.natural30={...m,events:{...ev},max};
let t=Q.create();t.weather='drought';run(t,360);results.drought90={...Q.metrics(t),events:{...t.aquaEvents}};t.weather='rain';run(t,120);results.recovery30={...Q.metrics(t),events:{...t.aquaEvents}};ck('reidratação',results.recovery30.wet>results.drought90.wet);ck('eclosão após chuva',results.recovery30.events.restingHatch>results.drought90.events.restingHatch);ck('recolonização após chuva',results.recovery30.events.recolonization>results.drought90.events.recolonization);
let z=Q.create();for(let r of z.aqua){for(let k of ['plankton','restingEggs','shrimp','shrimpEggs'])r[k]={c:0,n:0,p:0};r.shrimpCohorts=[]}run(z,8);ck('nenhum reaparecimento sem organismos ou ovos',Q.metrics(z).plankton===0&&Q.metrics(z).shrimp===0);let z2=Q.create();z2.light='dark';run(z2,8);ck('fotossíntese aquática desligada no escuro',z2.aquaEvents.fixed===0);fs.writeFileSync('results40.json',JSON.stringify({tests,results},null,2));console.log(tests);
